 function expectedForPlayer(s:Session,playerId:string){if(!s.participants.includes(playerId))return 0;if(s.mode==="fund")return s.contribution;const count=s.participants.length;return count?s.total/count:0;}
 function sessionReceived(s:Session){return payments.filter(p=>p.sessionId===s.id).reduce((sum,p)=>sum+p.amount,0);}
 function sessionOrganiserAdvance(s:Session){if(s.mode!=="fund"||!s.participants.length)return 0;return s.organiserAdvanceSettled?(s.organiserAdvanceSettledAmount??Math.max(0,s.total-sessionReceived(s))):Math.max(0,s.total-sessionReceived(s));}
 function fundBalanceAfterSession(s:Session){const relevant=sessions.filter(x=>x.mode==="fund"&&x.date<=s.date),ids=new Set(relevant.map(x=>x.id));const credits=payments.filter(p=>ids.has(p.sessionId)).reduce((n,p)=>n+p.amount,0),expenses=relevant.reduce((n,x)=>n+x.total,0),manual=fundTransactions.filter(t=>t.date<=s.date).reduce((n,t)=>n+(t.type==="Contribution"?t.amount:-t.amount),0),advances=relevant.filter(x=>!x.organiserAdvanceSettled).reduce((n,x)=>n+sessionOrganiserAdvance(x),0);return OPENING_FUND+credits-expenses+manual+advances;}
 function sessionFundSurplus(s:Session){return s.mode==="fund"?Math.max(0,sessionReceived(s)-s.total):0;}
 function latestSessionForPlayer(playerId:string){return [...sessions].filter(s=>s.participants.includes(playerId)).sort((a,b)=>b.date.localeCompare(a.date))[0];}
 function amountDueForSession(playerId:string,sessionId:string){const s=sessions.find(x=>x.id===sessionId);if(!s)return 0;const expected=expectedForPlayer(s,playerId);const paid=payments.filter(p=>p.playerId===playerId&&p.sessionId===sessionId).reduce((n,p)=>n+p.amount,0);return Math.max(0,expected-paid);}
